UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT 
		root_hobt.ID,
		root_hobt.RowStatus,
		root_hobt.RowVersion,
		root_hobt.Guid,
		i.FullName AS CreatedByUserID,
		root_hobt.StageChange,
		root_hobt.StageMeetingChange,
		root_hobt.StageVisitChange,
		root_hobt.Reason,
		root_hobt.CreatedDateTime,
		rs.Description AS StageName
FROM SJob.CustomFeeAmendment AS root_hobt
JOIN SJob.FeeAmendment AS fa ON (fa.ID = root_hobt.FeeAmendmentId)
JOIN SCore.Identities AS i ON (i.ID = root_hobt.CreatedByUserID)
JOIN SJob.RibaStages AS rs ON (rs.ID = root_hobt.StageId)
WHERE fa.Guid = [[ParentGuid]]
' WHERE ID = 254

